std::atomic<bool> ready{false};
int data = 0;

// 生产者线程：
void producer() {
    data = 42;
    ready.store(true, std::memory_order_release); // 屏障：保证 data=42 先于 ready 写入
}
// 消费者线程：
void consumer() {
    while (!ready.load(std::memory_order_acquire)) {} // 屏障：保证读取 data 在后
    assert(data == 42); // 绝不会失败！
}

